INSERT INTO `about_us` (`id`, `title`, `description`, `created_at`, `updated_at`) VALUES
(1, 'درباره دیار ابزار | فروشگاه تخصصی ابزارآلات ساختمانی و صنعتی', 'دیار ابزار، فروشگاه اینترنتی ابزارآلات ساختمانی و صنعتی؛ ارائه‌دهنده انواع ابزارهای برقی، دستی و تجهیزات موردنیاز پروژه‌های ساختمانی و فنی. هدف ما فراهم کردن تجربه‌ای آسان و مطمئن برای بررسی، انتخاب و خرید ابزار مناسب با نیاز شماست. در دیار ابزار، کیفیت، تنوع محصولات و رضایت مشتریان را در اولویت قرار می‌دهیم.', '2026-11-16 15:38:47', '2026-11-16 15:38:47');
