INSERT INTO `products` (`id`, `title`, `description`, `summary`, `primary_price`, `secondary_price`, `count`, `show_in_home`, `writer`, `publication`, `brand`, `created_at`, `updated_at`) VALUES
(12, 'دریل پیچ‌ گوشتی چکشی شارژی دو سرعته 14 ولت مدل : 8614  (2.46)', '<p>دریل پیچ‌ گوشتی‌ 8614 رونیکس، ابزار شارژی قدرتمند با سه عملکرد مجزای سوراخ‌کاری، پیچ‌کاری و سوراخ‌کاری چکشی است. این ابزار از یک سه‌ نظام اتوماتیک و قدرتمند 10 میلی‌متری و تمام فلزی بهره می‌برد و نسبت به فشار حاصل از فعالیت در سطوح متراکم مقاومت بسیار بالایی دارد.<br>طراحی ارگونومیک و مقاوم بدنه، گیربکس دو حالته، امکان تغییر گشتاور با تنظیمات کلاچ در 21 حالت مختلف، باتری لیتیوم یون&nbsp; با طول عمر بالا و کارکرد عالی، کیف BMC مقاوم به ضربه و ... تنها بخشی از مزایای این ابزار شارژی پرکاربرد هستند.<br><br></p>', NULL, NULL, NULL, 10, 1, NULL, NULL, NULL, '2026-11-17 16:49:00', '2026-11-19 12:37:47'),
(13, 'دریل شارژی مدل : 8612C  (2.13)', '<p>امروزه کاربرد دریل های شارژی بیش از پیش افزایش یافته است و به همین دلیل وجود آن در مجموعه ابزارهای خانگی و کارگاهی افراد لازم می باشد. به این ابزار لقب همه کاره را داده اند و می تواند کارهای مختلفی همانند سوراخ کاری سطوح جهت آویزان کردن قاب و باز و بسته کردن انواع پیچ را به راحتی انجام دهد. دریل های شارژی به دلیل عدم نیاز به برق مستقیم امکان کار در محیط های مختلف را فراهم می کنند و از این لحاظ مورد توجه قرار گرفته اند.<br><br>دریلی که در ادامه به معرفی آن خواهیم پرداخت مدل 8612C رونیکس است که با موتور قدرتمند، باتری لیتیوم یون 12 ولت و سرعت بالا کاربرد فراوانی در منازل و مشاغل مختلف دارد.</p>', NULL, NULL, NULL, 10, 1, NULL, NULL, NULL, '2026-11-17 16:57:51', '2026-11-19 12:49:12'),
(14, 'مدل : 2120  (2.08)  دریل چکشی 10میلی متر-750وات-آچاری', '<p><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">دریل چکشی 2120 رونیکس، با موتور قدرتمند 750 وات کار می‌کند که مجهز به آرمیچر و بالشتک‌های صنعتی است. این قطعات مطابق آخرین استانداردهای روز دنیا ساخته شده‌اند. این دریل، با ترکیب دو نیروی چرخشی و ضربه‌ای، سوراخ‌کاری معمولی و سوراخ‌کاری چکشی را در سطوح بسیار سخت مانند انواع دیوار به آسانی انجام می‌دهد. حداکثر سرعت گردش در این دریل چکشی پرقدرت 2800 دور بر دقیقه است.&nbsp;</span><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">سه‌نظام تمام‌فلزی، مستحکم و آچاری دریل 2120 رونیکس، 10 میلی‌متری است و در کنار بدنه‌ ارگونومیک، کوچک و 1,6 کیلوگرمی این دریل، قابلیت چکشی و قدرت مانور بالایی را در زوایای مختلف و مکان‌های تنگ و محدود ایجاد می‌کند. دریل‌ برقی 2120 رونیکس، با دقیق‌ترین سیستم‌های کنترل کیفی طراحی و تولید شده است، بنابراین کاربران با خیالی آسوده در طول ساعات کاری مستمر از این دستگاه باکیفیت و پرکاربرد استفاده می‌کنند.</span><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">در ادامه با دریل چکشی 10 میلی‌متری آچاری 750 وات رونیکس مدل 2120، بیشتر آشنا شوید.</span></p>', NULL, NULL, NULL, 10, 1, NULL, NULL, NULL, '2026-11-17 17:02:22', '2026-11-17 20:14:18'),
(15, 'مدل : 2210  (2.12)  دریل چکشی 13میلی متر-810وات-آچاری', '<p><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">دریل چکشی 2210 رونیکس، با موتور قدرتمند صنعتی 810 وات کار می‌کند؛ مجهز به آرمیچر و بالشتک‌های صنعتی با کیفیت ساخت بالا است و با ترکیب دو نیروی چرخشی و جنبشی (ضربه‌ای) در سطوح بسیار سخت مانند انواع دیوار، عمل سوراخ‌کاری معمولی و سوراخ‌کاری چکشی را به آسانی انجام می‌دهد. سیستم بلبرینگ دوبل در قسمت شفت این دریل، قابلیت متمایزی است که جهت افزایش قابلیت چکشی آن تعبیه شده است. در این دریل، حداکثر سرعت گردش در حالت آزاد، 3000 دور در دقیقه است که به وسیله‌ی کلید الکترونیک دیمردار کنترل سرعت تنظیم می‌شود.</span><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">سه نظام 13 میلی‌متری، تمام فلزی و مستحکم دریل چکشی 2210 رونیکس، آچاری بوده و آچار تعویض مته در بسته‌بندی آن ارائه می‌شود. وجود میله‌ی عمق‌سنج همراه این ابزار، تعیین و اندازه‌گیری عمق سوراخ‌کاری بر روی سطوح مختلف را برای کاربران ایجاد می‌کند. این دریل قدرتمند رونیکس، عملکرد فوق‌العاده‌ای را در سوراخ‌کاری سطوح مختلف و مصالح بتن، فلز و چوب نشان می‌دهد.</span><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">برای بررسی بیشتر مشخصات </span><strong style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; font-weight: bolder; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">دریل برقی چکشی 13 میلی‌متری آچاری 810 وات 3000 دور رونیکس با مدل 2210</strong><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">، به بخش شرح جزئیات محصول مراجعه کنید.</span><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">&nbsp;</span></p>', NULL, NULL, NULL, 1, 0, NULL, NULL, NULL, '2026-11-17 17:04:53', '2026-11-17 17:04:53'),
(16, 'مدل : 2410  (1.61)  همزن دو سرعته گیربکسی 1300 وات', '<p><span style=\"color: rgb(61, 61, 61); font-family: dana; font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">از دستگاه همزن برقی 2410 رونیکس، برای مخلوط‌کردن مصالح ساختمانی، مواد شیمیایی، ملات‌های با چگالی و غلظت بالا، رنگ، گچ، پرکننده‌های ساختمانی و مواد مختلف استفاده می‌شود. این دستگاه برای کار با تیغه‌های همزن تکی طراحی شده است. در این ابزار برقی رونیکس، نصب همزن به اشکال مختلف و نیز تنظیم سرعت الکترونیکی و مکانیکی به راحتی انجام می‌شود.</span><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><br style=\"box-sizing: border-box; font-family: dana; padding: 0px; margin: 0px; color: rgb(61, 61, 61); font-size: 16px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 300; letter-spacing: 0.024px; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoratio